import pandas as pd

def tabel_prioritas(df, kolom, progres, usaha):
    persen = df[kolom].mean() * 100
    t = pd.DataFrame({"persen": persen})
    t["skor"] = [persen[n] * progres[n] / usaha[n] for n in t.index]
    return t.sort_values("skor", ascending=False)

